{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Glycyrrhizin, a highly polar steroid-like triterpenoid glycoside, has an absolute oral bioavailability of approximately 0.25% in humans, demonstrating that extensive polar substitution on a steroid scaffold can produce very low oral absorption; this supports a low-F prediction for the similarly polyhydroxylated query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "AKBA, a pentacyclic triterpenoid with poor oral bioavailability in healthy volunteers due to low absorption and/or extensive metabolism, supports low systemic availability for structurally related polycyclic terpenoid/steroid scaffolds with polar functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Methylprednisolone, a corticosteroid sharing the steroid core, has an absolute oral bioavailability of 72.6% after oral solution, indicating that steroid scaffolds can be well absorbed; however, the query has many additional hydroxyls and a different side chain, so this high-F evidence transfers only weakly.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C50"],
      "claim": "Hydrocortisone has an absolute oral bioavailability of about 96% in humans, demonstrating high oral absorption for corticosteroids; the query's extra polar hydroxyls and altered side chain make this high-F evidence less applicable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a highly polar ecdysteroid with multiple hydroxyls; the most relevant polar steroid-like analogues (glycyrrhizin, AKBA) show low oral bioavailability, while high-F corticosteroid analogues are less polar and structurally distant. Thus F < 20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for 20-hydroxyecdysone is present in the evidence set.",
    "All retrieved analogues have low Morgan similarity (<0.25), limiting transferability.",
    "Human pharmacokinetic data for ecdysteroids are absent from the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

